"""build-deb.sh ships shell completions for hscl and hscl1, generated by the packaged binary itself (no hand-written copy to drift).

Uses a stand-in `dpkg-deb` and a stand-in binary that echoes its argv0 and arguments. Needs chmod/symlink semantics, so Windows
checkouts skip it (narrow, documented); Linux CI and the WSL clone run it.
"""
import os
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]

pytestmark = pytest.mark.skipif(sys.platform.startswith("win"), reason="needs POSIX symlinks and chmod (Linux CI runs this)")


def test_base_package_contains_completions_for_both_program_names(tmp_path):
    shim = tmp_path / "bin"
    shim.mkdir()
    (shim / "dpkg-deb").write_text(
        '#!/bin/sh\nstage="$3"; out="$4"\ncd "$stage" && find . -type f -printf "%p\n" | sort > "$out"\n', encoding="utf-8")
    (shim / "dpkg-deb").chmod(0o755)
    fake = tmp_path / "hscl"
    fake.write_text('#!/bin/sh\necho "# argv0=$(basename "$0") args=$*"\n', encoding="utf-8")
    fake.chmod(0o755)
    env = {**os.environ, "PATH": f"{shim}:{os.environ['PATH']}"}
    r = subprocess.run(["bash", str(ROOT / "scripts/build-deb.sh"), "hscl-base", str(tmp_path / "out"), "--bin", str(fake)],
                       capture_output=True, text=True, env=env)
    assert r.returncode == 0, r.stderr
    files = Path(r.stdout.strip().splitlines()[-1]).read_text(encoding="utf-8").splitlines()
    for want in [
        "./usr/share/bash-completion/completions/hscl", "./usr/share/bash-completion/completions/hscl1",
        "./usr/share/zsh/vendor-completions/_hscl", "./usr/share/zsh/vendor-completions/_hscl1",
        "./usr/share/fish/vendor_completions.d/hscl.fish", "./usr/share/fish/vendor_completions.d/hscl1.fish",
    ]:
        assert want in files, want
